def test_gate_call_precedes_training_initialization_in_source():
    """Structural guard: the gate call must appear before loader/model setup."""
    source = SCRIPT_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)

    run_fn = next(
        (
            node
            for node in ast.walk(tree)
            if isinstance(node, ast.FunctionDef) and node.name == "run_training_experiment"
        ),
        None,
    )
    assert run_fn is not None, "run_training_experiment not found in script"

    gate_line = None
    first_loader_line = None
    first_mkdir_line = None
    first_model_line = None

    for node in ast.walk(run_fn):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        name = func.id if isinstance(func, ast.Name) else (func.attr if isinstance(func, ast.Attribute) else "")
        if name == "verify_audio_pretraining_gates" and gate_line is None:
            gate_line = node.lineno
        elif name == "AudioDatasetLoader" and first_loader_line is None:
            first_loader_line = node.lineno
        elif name == "mkdir" and first_mkdir_line is None:
            first_mkdir_line = node.lineno
        elif name == "CompactTrainHornCNN" and first_model_line is None:
            first_model_line = node.lineno

    assert gate_line is not None, "verify_audio_pretraining_gates not called"
    assert first_loader_line is not None, "AudioDatasetLoader not found"
    assert first_mkdir_line is not None, "mkdir (run dir creation) not found"
    assert gate_line < first_loader_line, (
        f"Gate line {gate_line} must precede loader line {first_loader_line}"
    )
    assert gate_line < first_mkdir_line, (
        f"Gate line {gate_line} must precede mkdir line {first_mkdir_line}"
    )
    if first_model_line is not None:
        assert gate_line < first_model_line, (
            f"Gate line {gate_line} must precede model init line {first_model_line}"
        )

def test_no_source_recording_in_multiple_partitions(manifest_records):
    """Leakage Test 1: Verify each unique source recording appears in strictly one partition."""
    source_to_partitions: dict[str, set[str]] = {}
    for r in manifest_records:
        src = r["source_file"]
        source_to_partitions.setdefault(src, set()).add(r["partition"])

    for src, partitions in source_to_partitions.items():
        assert len(partitions) == 1, f"Data leakage detected! {src} appears in multiple partitions: {partitions}"

def test_no_sha256_duplicate_in_multiple_partitions(manifest_records):
    """Leakage Test 2: Verify no SHA-256 hash appears across multiple partitions."""
    sha_to_partitions: dict[str, set[str]] = {}
    for r in manifest_records:
        sha = r["source_sha256"]
        sha_to_partitions.setdefault(sha, set()).add(r["partition"])

    for sha, partitions in sha_to_partitions.items():
        assert len(partitions) == 1, f"SHA-256 duplicate leakage! Hash {sha[:12]} appears in multiple partitions: {partitions}"

def test_windows_from_same_source_remain_together(manifest_records):
    """Leakage Test 4: All sliding windows from a single source file must share the file's partition."""
    file_partitions: dict[str, str] = {}
    for r in manifest_records:
        fname = r["source_file"]
        part = r["partition"]
        if fname in file_partitions:
            assert file_partitions[fname] == part, f"Window partition mismatch for file {fname}"
        else:
            file_partitions[fname] = part

