def test_a_decreasing_clock_aborts_the_report():
    reads = {"n": 0}

    def clock():
        reads["n"] += 1
        # increases by 1 ms per read, except one read late in the measured region goes backwards
        return reads["n"] * 0.001 - (0.01 if reads["n"] == 40 else 0.0)

