def test_confusion_matrix_shape_includes_background():
    gt = [GroundTruthBox("img1", "front", box(0, 0, 10, 10))]
    pred = [PredictionBox("img1", "front", 0.9, box(0, 0, 10, 10))]
    metrics = evaluate_detection(gt, pred, ["front", "side", "rear"])
    for row in metrics.class_names + [BACKGROUND]:
        assert row in metrics.confusion_matrix
        for col in metrics.class_names + [BACKGROUND]:
            assert col in metrics.confusion_matrix[row]

def test_train_requires_ultralytics(tmp_path, monkeypatch):
    monkeypatch.delitem(sys.modules, "ultralytics", raising=False)
    import builtins

    real_import = builtins.__import__

    def blocked(name, *args, **kwargs):
        if name == "ultralytics":
            raise ImportError("blocked")
        return real_import(name, *args, **kwargs)

    monkeypatch.setattr(builtins, "__import__", blocked)
    adapter = UltralyticsYOLOAdapter()
    with pytest.raises(ConfigError):
        adapter.train(object(), tmp_path / "d.yaml", tmp_path)

def test_evaluate_returns_metrics(tmp_path, fake_ultralytics):
    adapter = UltralyticsYOLOAdapter()
    metrics = adapter.evaluate(tmp_path / "best.pt", tmp_path / "test.jsonl")
    assert metrics == {"mAP50": 0.81, "mAP50_95": 0.62}
